/*! html2canvas (offline shim)
 * Provides a minimal window.html2canvas(element, options) Promise<canvas>.
 * Not a full replacement for html2canvas.
 */
(function(){
  'use strict';

  function getTextSnapshot(el){
    var txt = '';
    try {
      txt = (el && (el.innerText || el.textContent) ? (el.innerText || el.textContent) : '');
    } catch (e) {
      txt = '';
    }
    txt = String(txt || '').replace(/\r\n?/g, '\n');
    return txt;
  }

  function canvasFromText(text, options){
    var opts = options || {};
    var canvas = document.createElement('canvas');
    var ctx = canvas.getContext('2d');

    var padding = 16;
    var fontSize = Number(opts.fontSize) || 14;
    var lineHeight = Math.round(fontSize * 1.4);
    var font = (opts.font || ('600 ' + fontSize + 'px system-ui, -apple-system, Segoe UI, Roboto, Arial'));

    ctx.font = font;

    var lines = String(text || '').split('\n');
    var maxW = 0;
    for (var i=0;i<lines.length;i++){
      var m = ctx.measureText(lines[i]);
      maxW = Math.max(maxW, Math.ceil(m.width));
    }
    var w = Math.max(320, maxW + padding*2);
    var h = Math.max(240, lines.length * lineHeight + padding*2);

    var scale = Number(opts.scale) || 2;
    canvas.width = Math.round(w * scale);
    canvas.height = Math.round(h * scale);
    canvas.style.width = w + 'px';
    canvas.style.height = h + 'px';

    ctx.setTransform(scale, 0, 0, scale, 0, 0);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0,0,w,h);

    ctx.font = font;
    ctx.fillStyle = '#111111';

    var y = padding + lineHeight;
    for (var j=0;j<lines.length;j++){
      ctx.fillText(lines[j], padding, y);
      y += lineHeight;
    }

    return canvas;
  }

  function supportsForeignObject(){
    // Very defensive: if anything throws, treat as unsupported.
    try {
      return !!(window.SVGForeignObjectElement);
    } catch(e){
      return false;
    }
  }

  function snapshotWithForeignObject(el, options){
    return new Promise(function(resolve, reject){
      try {
        var rect = el.getBoundingClientRect();
        var width = Math.max(1, Math.ceil(rect.width));
        var height = Math.max(1, Math.ceil(rect.height));

        var cloned = el.cloneNode(true);
        // Inline minimal base style to reduce surprises.
        var wrapper = document.createElement('div');
        wrapper.setAttribute('xmlns', 'http://www.w3.org/1999/xhtml');
        wrapper.style.width = width + 'px';
        wrapper.style.height = height + 'px';
        wrapper.style.background = '#ffffff';
        wrapper.appendChild(cloned);

        var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="'+width+'" height="'+height+'">'
          + '<foreignObject width="100%" height="100%">'
          + new XMLSerializer().serializeToString(wrapper)
          + '</foreignObject></svg>';

        var img = new Image();
        // Blob URL avoids some data-URI length limits
        var blob = new Blob([svg], {type: 'image/svg+xml;charset=utf-8'});
        var url = URL.createObjectURL(blob);

        img.onload = function(){
          try {
            URL.revokeObjectURL(url);
          } catch(_){ }

          try {
            var canvas = document.createElement('canvas');
            var scale = Number((options||{}).scale) || 2;
            canvas.width = Math.round(width * scale);
            canvas.height = Math.round(height * scale);
            canvas.style.width = width + 'px';
            canvas.style.height = height + 'px';

            var ctx = canvas.getContext('2d');
            ctx.setTransform(scale, 0, 0, scale, 0, 0);
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0,0,width,height);
            ctx.drawImage(img, 0, 0);
            resolve(canvas);
          } catch (e2){
            reject(e2);
          }
        };

        img.onerror = function(){
          try { URL.revokeObjectURL(url); } catch(_){}
          reject(new Error('foreignObject snapshot failed'));
        };

        img.src = url;
      } catch (e){
        reject(e);
      }
    });
  }

  window.html2canvas = function(el, options){
    var opts = options || {};
    // Best effort: foreignObject first, fallback to text
    if (el && supportsForeignObject()){
      return snapshotWithForeignObject(el, opts).catch(function(){
        return Promise.resolve(canvasFromText(getTextSnapshot(el), opts));
      });
    }
    return Promise.resolve(canvasFromText(getTextSnapshot(el), opts));
  };
})();
